now=datetime.now(timezone.utc).isoformat();packet=dict(recorded_at=now,entry=e['id'],source=ref(ROOT/'art/village/sources.json'),captured_actor=actor,body_model=bref,body_review=b['art_review'],equipment_bindings={},natural_equipment=[dict(part=p['id'],type=p['type'],item=p['defaultItem']) for p in actor['parts'] if p.get('defaultItem')],
 equipment_policy='Observed worn/held list is empty. Default Face Glowfish_Bite remains native natural attack behavior, not a carried object or clothing. No fins/head treated as independent articulated renderer bones.',body_policy='Two neutral color planes depict one normal whole catfish with intrinsic head, gills, barbels, four fins and source curl. Source metadata/species supports the plan; no humanoid model or new mutation limb. Exact current material/geometry and corrected square world frame are reused.',
 palette=dict(primary=actor.get('tileColor') or actor['foreground'],detail=actor['detailColor']),history=dict(report='docs/conversion-entries/BODY-GLOWFISH.html',source_packet=body['source'],front=body['front'],construction=body['construction'],actual_side_back=body['actual_side_back'],actual_refinement=body['actual_composed_refinement'],structural_review=body['structural_review'],material=body['material_selection'],frame_correction=body['frame_correction']),new_imagegen_calls=0,
 behavior_boundary='Native LightSource/Gills/DarkVision, water visibility, movement and natural bite remain native. No water/glow layer, fixed-purple fallback, demographics or simulation changes.',native_acceptance='Pending full-set generation gate: actual water/lighting/visibility, whole-body facing/pivot, palette OFF/ON, hurt/look/save and supported states.')
write('source-packet.json',packet);write('assembly-contract.json',dict(recorded_at=now,body=bref,frame=body['registration'],equipment={},views=dict(south='Selected curled south swimming-plane catfish, head toward south; dorsal/lateral/tail fins keep their identities.',east='Whole selected animal turns east under actual live fish-pawn map camera; no independent head/fin turn.',north='Whole selected animal turns north in swimming plane; source curl and fin count unchanged.',west='Supported mirror of east, whole geometry and tint ownership together.'),pivot='Fixed384,384 trunk/swim pivot, not human ground feet. Both color planes share identical physical frame and eventual native transform.',palette=packet['palette'],policy=packet['equipment_policy'],native_activation=False))
pal=read(ROOT/'evidence/joppa-anatomy-study.json')['native_palette'];colors={role:np.array(tuple(bytes.fromhex(pal[(actor['detailColor'] if role=='detail' else actor.get('tileColor') or actor['foreground']).replace('&','')[0]]))) for role in ['foreground','detail']};groups={k:{} for k in ['neutral','native']};checks={}
for f in FACES:
 neutral=Image.new('RGBA',tuple(body['canvas']));native=Image.new('RGBA',tuple(body['canvas']))
 for row in sorted(body['views'][f],key=lambda r:r['layer']):
  assert ref(ROOT/row['public_file'])['sha256']==row['sha256'];image=im(ROOT/row['public_file']);a=np.array(image);assert not np.ptp(a[:,:,:3].astype(int),axis=2).any();neutral.alpha_composite(image);a[:,:,:3]=np.uint8(np.round(a[:,:,:3].mean(2)[:,:,None]*colors[row['color_role']]/255));a[a[:,:,3]==0,:3]=0;native.alpha_composite(Image.fromarray(a));assert abs(row['width']*(2/3)/768-row['height']/768)<1e-14
 assert np.array_equal(np.array(neutral),np.array(im(ROOT/body['channels'][f]['neutral_assembly']['path'])))
 expected=np.array(im(ROOT/body['channels'][f]['native_preview']['path']));actual=np.array(native);diff=np.abs(actual.astype(int)-expected.astype(int));covered=actual[:,:,3]>0;assert diff[:,:,3].max()==0 and diff[:,:,:3][covered].max()<=1
 neutral.save(HERE/f'neutral-{f}.png');native.save(HERE/f'native-palette-{f}.png');groups['neutral'][f]=neutral;groups['native'][f]=native;checks[f]=dict(source_hashes_current=True,body_pixels_frame_pivot_unchanged=True,neutral_exact_body_reference=True,native_rounding_max_rgb=int(diff[:,:,:3][covered].max()),native_alpha_error=int(diff[:,:,3].max()),production_neutral_equal_RGB=True,physical_canvas_world=[row['width']*(2/3),row['height']],worn_items=0)
