write('composition-checks.json',checks);font=ImageFont.truetype('C:/Windows/Fonts/consola.ttf',14)
for key,name in [('neutral','neutral-comparison.png'),('native','native-palette-comparison.png')]:
 out=Image.new('RGB',(1200,420),'#142823');d=ImageDraw.Draw(out);d.text((15,15),'GLOWFISH / '+key.upper()+' / actual empty outfit, current source-bound whole fish',font=font,fill='#e3cf43')
 for i,f in enumerate(FACES):
  bg=Image.new('RGBA',tuple(body['canvas']),'#20382d');bg.alpha_composite(groups[key][f]);out.paste(bg.resize((280,280),Image.Resampling.LANCZOS).convert('RGB'),(10+i*300,55));d.text((15+i*300,360),f.upper(),font=font,fill='#e3cf43')
 d.text((15,394),'Neutral planes stay gray; native m/C independent. Light/water behavior and native acceptance pending.',font=font,fill='#e5e8d8');out.save(HERE/name)
out=Image.new('RGB',(800,360),'#142823');d=ImageDraw.Draw(out)
for j,key in enumerate(['neutral','native']):
 for i,f in enumerate(FACES):
  image=groups[key][f].resize((64,64),Image.Resampling.LANCZOS);out.paste(image,(15+i*200,15+j*170),image);zoom=image.resize((128,128),Image.Resampling.NEAREST);out.paste(zoom,(75+i*200,15+j*170),zoom);d.text((15+i*200,150+j*170),f.upper(),font=font,fill='#e3cf43')
out.save(HERE/'game-scale-review.png')
for step,action,names in [('resolve_individual_race_and_runtime_metadata','Resolve actual Glowfish528/catfish, Fish topology, four fins and natural default Bite; no worn/held objects.',['source-packet.json']),('verify_body_and_every_equipped_item_dependencies','Verify current generation-ready intrinsic fish body, actual complete source-generation history, independent tint planes and corrected world-square frame.',['assembly-contract.json','composition-checks.json']),('assemble_without_baking_equipment','Compose exact current two-plane animal and native m/C colors with empty equipment list. Actual all-view review pending.',['assemble.py','model.json','neutral-comparison.png','native-palette-comparison.png','game-scale-review.png'])]:
 e['process_log'].append(dict(timestamp=now,step=step,action=action,inputs=[bref],outputs=[ref(HERE/n) for n in names],review=action,result='REQUIRES REVIEW' if step=='assemble_without_baking_equipment' else 'PASS'))
